INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q65066872', 'Kuwaiti–Rashidi War', 'The Kuwaiti–Rashidi war was a conflict between the Sheikhdom of Kuwait and the Emirate of Jabal Shammar which was fought from 1900 to 1901. It began in mid-December 1900, when the emir of Kuwait, Mubarak Al-Sabah launched a raid into central Arabia.', 1900, NULL, NULL, 1901, NULL, NULL, 'year', '1900–1901', 37, 'https://en.wikipedia.org/wiki/Kuwaiti%E2%80%93Rashidi_war'),
  ('Q6449024', 'Kuwait–Nejd Border War', 'The Kuwait–Najd War erupted in the aftermath of World War I. The war occurred due to Ibn Saud of Najd''s desire to annex Kuwait. The sharpened conflict between Kuwait and Najd led to the death of hundreds of Kuwaitis.', 1919, NULL, NULL, 1920, NULL, NULL, 'year', '1919–1920', 43, 'https://en.wikipedia.org/wiki/Kuwait%E2%80%93Najd_War'),
  ('Q37643', 'Gulf War', 'The Gulf War was an armed conflict between Iraq and a 42-country coalition led by the United States in response to the Iraqi invasion of Kuwait on 2 August 1990. The coalition''s efforts were carried out in two phases: Operation Desert Shield, which marked the military buildup in the Persian Gulf region from August 1990 to January 1991; and Operation Desert Storm, which began with the bombing campaign against Iraq on 17 January and continued until the liberation of Kuwait on 28 February.', 1990, 8, 2, 1991, 2, 28, 'day', '2 August 1990 – 28 February 1991', 90, 'https://en.wikipedia.org/wiki/Gulf_War'),
  ('Q856650', 'Iraqi invasion of Kuwait', 'The Iraqi invasion of Kuwait, codenamed Project 17, began on 2 August 1990 and marked the beginning of the Gulf War. After defeating the State of Kuwait on 4 August 1990, Iraq went on to militarily occupy the country for the next seven months.', 1990, 8, 2, 1990, 8, 4, 'day', '2 August 1990 – 4 August 1990', 72, 'https://en.wikipedia.org/wiki/Iraqi_invasion_of_Kuwait'),
  ('Q4870849', 'Battle of Dasman Palace', 'The Battle of Dasman Palace (Arabic: معركة قصر دسمان maʿraka Qaṣr Dasmān), also called the Battle of Dasman, took place between the Kuwaiti and Iraqi forces during the Iraqi invasion of Kuwait on 2 August 1990.', 1990, 8, 2, NULL, NULL, NULL, 'day', '2 August 1990', 45, 'https://en.wikipedia.org/wiki/Battle_of_Dasman_Palace'),
  ('Q4870995', 'Battle of Failaka', 'The Battle of Failaka broke out between the Kuwaiti garrison of Failaka Island and attacking Iraqi forces during the Iraqi Invasion of Kuwait, on 2 August 1990. The Kuwaiti garrison consisted of an infantry company and a company of border guards, in addition to air defense company armed with Hawk SAMs.', 1990, 8, 2, NULL, NULL, NULL, 'day', '2 August 1990', 37, 'https://en.wikipedia.org/wiki/Battle_of_Failaka'),
  ('Q4872876', 'Battle of the Bridges', 'The Battle of the Bridges (Arabic: معركة الجسور) was a battle that took place on 2 August 1990 in Kuwait, following the Iraqi invasion of Kuwait.', 1990, 8, 2, NULL, NULL, NULL, 'day', '2 August 1990', 39, 'https://en.wikipedia.org/wiki/Battle_of_the_Bridges'),
  ('Q6541036', 'Liberation of Kuwait Campaign', 'The Liberation of Kuwait campaign was between 24 and 28 February 1991, consisting of a major ground offensive into Iraqi-occupied Kuwait following the successful Gulf War air campaign. Approximately 650,000 troops of the American-led 42-country coalition swept into Kuwait to find the bulk of the 500,000 Iraqi troops surrendering en masse, but there were still pockets of resistance in some parts of the country.', 1991, 2, 28, 1991, 2, 28, 'day', '28 February 1991', 41, 'https://en.wikipedia.org/wiki/Liberation_of_Kuwait_campaign'),
  ('Q19428991', 'Battle of Kuwait International Airport', 'The Battle of Kuwait International Airport occurred on February 27, 1991, during the 1st Gulf War. It was a tank battle between the United States (as part of the Coalition of the Gulf War) and Iraq.', 1991, 2, 27, NULL, NULL, NULL, 'day', '27 February 1991', 37, 'https://en.wikipedia.org/wiki/Battle_of_Kuwait_International_Airport'),
  ('Q428733', 'Kuwaiti protests', 'The Kuwaiti protests refers to the series of 2011–2012 demonstrations for government reforms in the state of Kuwait. In November 2011, the government of Kuwait resigned in response to the protests, making Kuwait one of several countries affected by the Arab Spring to experience major governmental changes due to unrest.', 2011, NULL, NULL, NULL, NULL, NULL, 'year', '2011', 45, 'https://en.wikipedia.org/wiki/Kuwaiti_protests_(2011%E2%80%932012)'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q126539425', '2024 Mangaf Building Fire', 'On 12 June 2024, an early-morning fire broke out at a residential building in Mangaf in Kuwait''s Ahmadi Governorate housing 196 male migrant workers of NBTC Group, killing 50 migrant workers, at least 46 of whom were from India, and injuring around 50 others. Most victims died of smoke inhalation, while others were fatally injured from falling.', 2024, 6, 12, NULL, NULL, NULL, 'day', '12 June 2024', 48, 'https://en.wikipedia.org/wiki/2024_Mangaf_building_fire');

